from pathlib import Path
p = Path('/home/ubuntu/global-ai-coach/client/src/pages/Home.tsx')
s = p.read_text()

s = s.replace('  const chartRef = useRef<HTMLDivElement>(null);\n', '  const chartRef = useRef<HTMLDivElement>(null);\n  const deletedRangeRef = useRef<{ name: string; startDate: string; endDate: string } | null>(null);\n', 1)
s = s.replace('  const deleteSavedDateRange = trpc.profile.deleteDateRange.useMutation({ onSuccess: () => { void savedDateRanges.refetch(); toast.success("Date range deleted"); } });\n', '  const deleteSavedDateRange = trpc.profile.deleteDateRange.useMutation({ onSuccess: () => { void savedDateRanges.refetch(); toast("Date range deleted", { action: { label: "Undo", onClick: () => { const deleted = deletedRangeRef.current; if (deleted) saveDateRange.mutate(deleted); } } }); } });\n', 1)
s = s.replace('  function removeSavedRange(name: string) {\n    deleteSavedDateRange.mutate({ name });\n', '  function removeSavedRange(name: string) {\n    deletedRangeRef.current = savedDateRanges.data?.find((range) => range.name === name) || null;\n    deleteSavedDateRange.mutate({ name });\n', 1)

start = s.index('function SkillTrendChart(')
end = s.index('\nfunction parseSkillTrends', start)
component = '''function SkillTrendChart({ series, range, peerAverages }: { series: Array<{ weekStart: Date; skillTrends: string | null }>; range: number; peerAverages: Array<{ skill: string; score: number; attempts: number; sampleSize?: number; confidence?: string }> }) {
  const [zoom, setZoom] = useState(1);
  const [windowStart, setWindowStart] = useState(0);
  const [hovered, setHovered] = useState<{ skill: string; week: string; score: number; attempts: number; delta: number | null } | null>(null);
  const touchStart = useRef<{ x: number; y: number; distance: number | null } | null>(null);
  const windowSize = Math.max(2, Math.ceil(range / zoom));
  const maxStart = Math.max(0, series.length - windowSize);
  const visibleSeries = series.slice(Math.min(windowStart, maxStart), Math.min(windowStart, maxStart) + windowSize);
  function pinchDistance(touches: TouchList) { return touches.length >= 2 ? Math.hypot(touches[0].clientX - touches[1].clientX, touches[0].clientY - touches[1].clientY) : null; }
  function onTouchStart(event: React.TouchEvent<HTMLDivElement>) { touchStart.current = { x: event.touches[0].clientX, y: event.touches[0].clientY, distance: pinchDistance(event.touches) }; }
  function onTouchMove(event: React.TouchEvent<HTMLDivElement>) { const startTouch = touchStart.current; if (!startTouch || !startTouch.distance) return; const currentDistance = pinchDistance(event.touches); if (!currentDistance) return; const ratio = currentDistance / startTouch.distance; if (ratio > 1.12) { setZoom((value) => Math.min(4, value + 1)); touchStart.current = { ...startTouch, distance: currentDistance }; } else if (ratio < 0.88) { setZoom((value) => Math.max(1, value - 1)); touchStart.current = { ...startTouch, distance: currentDistance }; } }
  function onTouchEnd(event: React.TouchEvent<HTMLDivElement>) { const startTouch = touchStart.current; touchStart.current = null; if (!startTouch || startTouch.distance) return; const dx = event.changedTouches[0].clientX - startTouch.x; const dy = event.changedTouches[0].clientY - startTouch.y; if (Math.abs(dx) < 45 || Math.abs(dx) < Math.abs(dy)) return; setWindowStart((value) => Math.max(0, Math.min(maxStart, value + (dx < 0 ? 1 : -1)))); }
  const grouped = new Map<string, Array<{ week: string; score: number; attempts: number; delta: number | null }>>();
  for (const point of visibleSeries.reverse()) {
    const trends = point.skillTrends ? parseSkillTrends(point.skillTrends) : [];
    for (const trend of trends) {
      const values = grouped.get(trend.skill) || [];
      const previous = values[values.length - 1];
      values.push({ week: new Date(point.weekStart).toLocaleDateString(undefined, { month: "short", day: "numeric" }), score: trend.score, attempts: trend.attempts, delta: previous ? trend.score - previous.score : null });
      grouped.set(trend.skill, values);
    }
  }
  const skills = Array.from(grouped.entries()).slice(0, 4);
  return <div className="rounded-2xl border border-slate-200 bg-white p-4" onTouchStart={onTouchStart} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-widest text-slate-500">Skill progress over time</p><p className="mt-1 text-sm text-slate-600">Hover or use arrow keys · swipe to move · pinch to zoom</p></div><div className="flex items-center gap-1"><Button variant="outline" size="sm" onClick={() => { setZoom((value) => Math.max(1, value - 1)); setWindowStart(0); }} aria-label="Zoom out trend chart">−</Button><span className="min-w-16 text-center text-xs text-slate-500">{zoom}× zoom</span><Button variant="outline" size="sm" onClick={() => { setZoom((value) => Math.min(4, value + 1)); setWindowStart(0); }} aria-label="Zoom in trend chart">+</Button><TrendingUp size={18} className="ml-2 text-emerald-700" /></div></div>{skills.length ? <div className="mt-4 space-y-5">{skills.map(([skill, values]) => { const peer = peerAverages.find((item) => item.skill === skill); return <div key={skill}><div className="mb-1 flex flex-wrap justify-between gap-2 text-xs"><span className="font-medium text-slate-800">{skill}</span><span className="text-slate-500">{values[values.length - 1]?.score}/10 latest · peer {peer?.score ?? "—"} {peer ? `· n=${peer.sampleSize ?? 0} · ${peer.confidence ?? "low"} confidence` : ""}</span></div><div className="relative"><div className="flex items-end gap-2">{values.map((value, index) => <div key={`${skill}-${value.week}`} className="relative flex-1 outline-none" tabIndex={0} onMouseEnter={() => setHovered({ skill, ...value })} onMouseLeave={() => setHovered(null)} onFocus={() => setHovered({ skill, ...value })} onBlur={() => setHovered(null)} onKeyDown={(event) => { if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return; event.preventDefault(); const next = Math.max(0, Math.min(values.length - 1, index + (event.key === "ArrowRight" ? 1 : -1))); setHovered({ skill, ...values[next] }); (event.currentTarget.parentElement?.children[next] as HTMLElement | undefined)?.focus(); }}><div className="h-16 rounded-t-lg bg-slate-100 p-1"><div className="h-full rounded-md bg-emerald-500 transition-all" style={{ height: `${Math.max(8, value.score * 10)}%` }} /></div><p className="mt-1 truncate text-[10px] text-slate-500">{value.week}</p>{hovered?.skill === skill && hovered.week === value.week && <div className="absolute bottom-full left-1/2 z-20 mb-2 w-36 -translate-x-1/2 rounded-lg bg-slate-950 p-2 text-[11px] text-white shadow-lg"><p className="font-semibold">{value.week}</p><p>Score: {value.score}/10</p><p>Attempts: {value.attempts}</p><p className={value.delta === null ? "text-slate-300" : value.delta >= 0 ? "text-lime-300" : "text-rose-300"}>{value.delta === null ? "First saved point" : `${value.delta >= 0 ? "+" : ""}${value.delta} vs prior`}</p></div>}</div>)}</div>{peer && <div className="pointer-events-none absolute left-0 right-0 border-t border-dashed border-cyan-600" style={{ bottom: `${peer.score * 10}%` }}><span className="absolute -top-5 right-0 rounded bg-cyan-50 px-1 text-[10px] font-medium text-cyan-700">Peer {peer.score}/10 · n={peer.sampleSize ?? 0} · {peer.confidence ?? "low"}</span></div>}</div></div>; })}</div> : <p className="mt-4 text-sm text-slate-500">Generate a weekly summary after practicing to populate your trend chart.</p>}</div>;
}'''
s = s[:start] + component + s[end:]
p.write_text(s)
